<?php
declare(strict_types=1);
require_once __DIR__.'/../includes/auth.php'; require_admin(); require_once __DIR__.'/../includes/functions.php';
$pdo=db(); $id=(int)($_GET['id']??0); $isNew=$id<=0; $c=null;
if(!$isNew){$q=$pdo->prepare('SELECT * FROM categorias WHERE id=?');$q->execute([$id]);$c=$q->fetch();if(!$c)exit('Categoría no encontrada.');}
$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 check_csrf(); $action=(string)($_POST['action']??'save');
 if($action==='delete'){
   if($isNew)exit('Categoría no válida.');
   $q=$pdo->prepare('SELECT COUNT(*) FROM productos WHERE categoria_id=?');$q->execute([$id]);$count=(int)$q->fetchColumn();
   if($count>0){$err='No se puede eliminar esta categoría porque tiene '.$count.' producto(s). Mueve o elimina esos productos primero.';}
   else{$pdo->prepare('DELETE FROM categorias WHERE id=?')->execute([$id]);header('Location:index.php#categorias');exit;}
 } else {
   $nombre=trim((string)($_POST['nombre']??''));$orden=(int)($_POST['orden']??0);$activa=isset($_POST['activa'])?1:0;
   if($nombre===''){$err='El nombre de la categoría es obligatorio.';}
   if(!$err){
     if($orden<=0){$orden=(int)$pdo->query('SELECT COALESCE(MAX(orden),0)+1 FROM categorias')->fetchColumn();}
     if($isNew){$q=$pdo->prepare('INSERT INTO categorias(nombre,orden,activa) VALUES(?,?,?)');$q->execute([$nombre,$orden,$activa]);}
     else{$q=$pdo->prepare('UPDATE categorias SET nombre=?,orden=?,activa=? WHERE id=?');$q->execute([$nombre,$orden,$activa,$id]);}
     header('Location:index.php#categorias');exit;
   }
 }
}
$name=$c['nombre']??'';$order=(int)($c['orden']??0);$active=(int)($c['activa']??1);
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=h($isNew?'Nueva categoría':'Editar categoría')?> · Snackliciosos</title><link rel="stylesheet" href="style.css?v=11"><link rel="stylesheet" href="catalogo.css?v=12"></head><body><?php require __DIR__.'/sidebar.php'; ?><main class="wrap admin-content"><?php if($err):?><div class="alert error"><?=h($err)?></div><?php endif;?><section class="hero"><div><span class="eyebrow">ORGANIZACIÓN · CASCADA</span><h1><?=h($isNew?'Nueva categoría':'Editar categoría')?></h1><p>Organiza el catálogo con una captura corta y clara.</p></div></section><section class="card cascade-card"><form class="form" method="post" id="categoryWizard"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="save"><div class="wizard-progress"><span class="wizard-step-dot active"></span><span class="wizard-step-dot"></span><span class="wizard-step-dot"></span></div><div class="wizard-pane active"><span class="eyebrow">01 · IDENTIDAD</span><h2 class="wizard-question">¿Cómo se llamará?</h2><p class="wizard-help">Usa un nombre corto que el equipo pueda reconocer de inmediato.</p><label>Nombre<input id="catName" name="nombre" value="<?=h($name)?>" required autofocus placeholder="Ej. Fresas con crema"></label><div class="wizard-actions"><a class="btn btn-light" href="index.php#categorias">Cancelar</a><button class="btn btn-primary" type="button" data-next>Continuar →</button></div></div><div class="wizard-pane"><span class="eyebrow">02 · ORDEN</span><h2 class="wizard-question">¿Dónde debe aparecer?</h2><p class="wizard-help">El orden controla la posición de la categoría en el TPV y el menú.</p><label>Orden<input name="orden" type="number" min="0" value="<?=$order?>"><span class="field-hint">0 = colocar automáticamente al final.</span></label><div class="wizard-summary">Vista previa: <strong id="catPreview"><?=h($name?:'Nueva categoría')?></strong></div><div class="wizard-actions"><button class="btn btn-light" type="button" data-prev>← Atrás</button><button class="btn btn-primary" type="button" data-next>Continuar →</button></div></div><div class="wizard-pane"><span class="eyebrow">03 · ESTADO</span><h2 class="wizard-question">¿La mostramos ahora?</h2><p class="wizard-help">Una categoría inactiva puede conservarse sin aparecer en el TPV ni en el menú cliente.</p><label class="check"><input type="checkbox" name="activa" <?=$active?'checked':''?>> Categoría activa</label><div class="wizard-summary"><strong id="catFinal"><?=h($name?:'Nueva categoría')?></strong><br><span id="catFinalState"><?=$active?'Aparecerá en el catálogo.':'Quedará oculta.'?></span></div><div class="wizard-actions"><button class="btn btn-light" type="button" data-prev>← Atrás</button><button class="btn btn-primary" type="submit"><?=h($isNew?'✓ CREAR CATEGORÍA':'✓ GUARDAR CAMBIOS')?></button></div></div></form></section><?php if(!$isNew):?><section class="card dangerCard"><h2>Eliminar categoría</h2><p class="muted">Solo podrás eliminarla si no tiene productos asociados.</p><form method="post" id="deleteCategoryForm"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="delete"><button class="btn btn-danger" type="submit">🗑️ ELIMINAR CATEGORÍA</button></form></section><?php endif;?></main><script>(function(){const f=document.getElementById('categoryWizard'),p=[...f.querySelectorAll('.wizard-pane')],d=[...f.querySelectorAll('.wizard-step-dot')];let i=0;function ok(){for(const x of p[i].querySelectorAll('input[required]'))if(!x.checkValidity()){x.reportValidity();return false}return true}function r(){p.forEach((x,n)=>x.classList.toggle('active',n===i));d.forEach((x,n)=>x.classList.toggle('active',n<=i));document.getElementById('catPreview').textContent=document.getElementById('catName').value||'Nueva categoría';document.getElementById('catFinal').textContent=document.getElementById('catName').value||'Nueva categoría';document.getElementById('catFinalState').textContent=f.querySelector('[name="activa"]').checked?'Aparecerá en el catálogo.':'Quedará oculta.'}f.querySelectorAll('[data-next]').forEach(b=>b.onclick=()=>{if(ok()&&i<p.length-1){i++;r()}});f.querySelectorAll('[data-prev]').forEach(b=>b.onclick=()=>{if(i){i--;r()}});document.getElementById('deleteCategoryForm')?.addEventListener('submit',e=>{if(!confirm('¿Eliminar esta categoría? Esta acción no se puede deshacer.'))e.preventDefault()});r()})();</script></body></html>
